def f(g):
    H,W=len(g),len(g[0])
    div_row=[i for i in range(H) if len(set(g[i]))==1 and g[i][0]!=0]
    div_col=[c for c in range(W) if len({g[i][c] for i in range(H)})==1 and g[0][c]!=0]
    if div_row:
        d=div_row[0]; A=[list(r) for r in g[:d]]; B=[list(r) for r in g[d+1:]]
    else:
        c=div_col[0]; A=[r[:c] for r in g]; B=[r[c+1:] for r in g]
    return [[2 if a!=0 and b!=0 else 0 for a,b in zip(ra,rb)] for ra,rb in zip(A,B)]
